class Library {
  constructor() {
    this.books = new Map();
  }

  addBook(isbn, title, copies = 1) {
    // Validate copies parameter
    if (!Number.isInteger(copies) || copies <= 0) {
      throw new Error("copies must be a positive integer");
    }

    if (this.books.has(isbn)) {
      // If ISBN already exists, add to existing copies
      const existingBook = this.books.get(isbn);
      existingBook.copies += copies;
    } else {
      // Add new book
      this.books.set(isbn, { title, copies });
    }
  }

  copies(isbn) {
    const book = this.books.get(isbn);
    return book ? book.copies : 0;
  }

  titles() {
    const titles = [];
    for (const book of this.books.values()) {
      titles.push(book.title);
    }
    return titles.sort();
  }
}

// Export the Library class
module.exports = { Library };

// Test asserts
const library = new Library();

// Test addBook with new book
library.addBook("978-0-123456-78-9", "The Great Gatsby", 3);
console.assert(library.copies("978-0-123456-78-9") === 3, "Should have 3 copies");

// Test addBook with existing ISBN (should add copies)
library.addBook("978-0-123456-78-9", "Different Title", 2);
console.assert(library.copies("978-0-123456-78-9") === 5, "Should have 5 copies total");
console.assert(library.titles().includes("The Great Gatsby"), "Should have the original title");

// Test addBook with default copies
library.addBook("978-0-987654-32-1", "1984");
console.assert(library.copies("978-0-987654-32-1") === 1, "Should have 1 copy with default");

// Test copies with unknown ISBN
console.assert(library.copies("unknown") === 0, "Should return 0 for unknown ISBN");

// Test titles() returns sorted titles
library.addBook("978-0-111111-11-1", "Animal Farm", 1);
const titles = library.titles();
console.assert(titles[0] === "1984", "Should be sorted alphabetically");
console.assert(titles[1] === "Animal Farm", "Should be sorted alphabetically");
console.assert(titles[2] === "The Great Gatsby", "Should be sorted alphabetically");

// Test error for invalid copies
try {
  library.addBook("978-0-222222-22-2", "Test Book", 0);
  console.assert(false, "Should have thrown an error for 0 copies");
} catch (e) {
  console.assert(e.message === "copies must be a positive integer", "Should throw correct error");
}

try {
  library.addBook("978-0-333333-33-3", "Test Book", -1);
  console.assert(false, "Should have thrown an error for negative copies");
} catch (e) {
  console.assert(e.message === "copies must be a positive integer", "Should throw correct error");
}

try {
  library.addBook("978-0-444444-44-4", "Test Book", 1.5);
  console.assert(false, "Should have thrown an error for non-integer copies");
} catch (e) {
  console.assert(e.message === "copies must be a positive integer", "Should throw correct error");
}

console.log("All asserts passed!");

